import assert from 'node:assert/strict';
const root=process.argv[2];
const outcomes=[];
async function check(name,fn){try{await fn();outcomes.push({name,pass:true});}catch(e){if(e.code!=='ERR_ASSERTION')throw e;outcomes.push({name,pass:false,actual:e.actual,expected:e.expected});}}

import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';
const server=Bun.spawn([process.execPath,root+'/dist/server.mjs'],{cwd:root,stdout:'pipe',stderr:'pipe',env:{PATH:process.env.PATH,SYNTHETIC_PARSER_SECRET:'synthetic-only'}});const reader=server.stdout.getReader();const first=await reader.read();const port=Number(new TextDecoder().decode(first.value).trim());if(!Number.isInteger(port)||port<1)throw new Error('invalid server startup');const url='http://localhost:'+port;const encode=xml=>Buffer.concat([Buffer.from('SHOPPDF'),gzipSync(xml)]);const send=(id,bytes)=>fetch(url+'/upload?id='+id,{method:'POST',body:bytes});
try{
await check('normal file still parses through built artifact',async()=>{const response=await send('ordinary',encode('<title>Supplies</title>'));assert.equal(response.status,200);assert.equal((await response.json()).title,'Supplies');});
await check('parser is a separate process with empty environment',async()=>{const response=await send('probe',encode('<probe/>'));assert.equal(response.status,200);const probe=JSON.parse((await response.json()).title);assert.notEqual(probe.pid,server.pid);assert.deepEqual(probe.env,[]);});
await check('RSS limit stops a small-output memory allocation',async()=>{const response=await send('rss',encode('<allocate/>'));assert.equal(response.status,422);assert.deepEqual(await response.json(),{kind:'unreadable',kept:true});});
await check('generated decompression bomb refused while server and deposited file survive',async()=>{const bomb=encode('<title>Bomb</title>'+' '.repeat(32*1024*1024));assert.ok(bomb.length<65536);const response=await send('bomb',bomb);assert.equal(response.status,422);assert.deepEqual(await response.json(),{kind:'unreadable',kept:true});assert.equal(await (await fetch(url+'/health')).text(),'alive');assert.equal(await (await fetch(url+'/attachment?id=bomb')).text(),createHash('sha256').update(bomb).digest('hex'));});
await check('deadline and event-loop isolation',async()=>{const started=performance.now();const pending=send('slow',encode('<title>Slow</title><work delay="1000"/>'));await Bun.sleep(20);const healthy=await fetch(url+'/health');assert.equal(healthy.status,200);assert.ok(performance.now()-started<400,'health blocked by parsing');const result=await pending;assert.equal(result.status,422);});
await check('saturated queue has distinct retryable refusal',async()=>{const slow=encode('<title>Slow</title><work delay="1000"/>');const pending=[send('s1',slow),send('s2',slow),send('s3',slow)];await Bun.sleep(20);const fourth=await send('s4',slow);assert.equal(fourth.status,503);assert.equal((await fourth.json()).kind,'busy');assert.ok(fourth.headers.get('retry-after'));await Promise.all(pending);});
}finally{server.kill();await server.exited;}
console.log(JSON.stringify(outcomes,null,2));process.exit(outcomes.every(x=>x.pass)?0:10);
